import {answerInterpretation} from './answer-interpretations.mjs?v=1';
import {simulatedComparison} from './report-benchmark.mjs?v=1';

// Editorial selections, not a severity scale: use reported groups, prefer area
// variety, then retain questionnaire order for otherwise equivalent responses.
function acrossAreas(items,limit){
 const chosen=[],seen=new Set();
 for(const item of items){const area=Math.floor(item.index/6);if(!seen.has(area)){chosen.push(item);seen.add(area);}if(chosen.length===limit)return chosen;}
 for(const item of items){if(!chosen.includes(item))chosen.push(item);if(chosen.length===limit)break;}
 return chosen;
}
export function consolidatedDetails(snapshot){
 const strengths=snapshot.items.filter(i=>i.category==='support');
 const growth=snapshot.items.filter(i=>i.category==='focus');
 const sometimes=snapshot.items.filter(i=>i.category==='varies');
 const byClarity=items=>[...items].sort((a,b)=>Math.abs(b.value-2)-Math.abs(a.value-2)||a.index-b.index);
 const priorities=acrossAreas(byClarity(growth.length?growth:sometimes.length?sometimes:strengths),3);
 const comparison=acrossAreas([strengths[0],growth[0],sometimes[0],...snapshot.items].filter(Boolean).filter((item,i,all)=>all.findIndex(other=>other.index===item.index)===i),3);
 return {strengths:acrossAreas(byClarity(strengths),4),attention:acrossAreas(byClarity(growth.length?growth:sometimes),4),priorities,comparison,mode:growth.length?'growth':sometimes.length?'explore':'maintain'};
}

export function consolidatedDetailsMarkup(snapshot,{language='en',areas,categories,icon,escapeHTML:esc}){
 const t=(en,hi)=>language==='hi'?hi:en,details=consolidatedDetails(snapshot);
 const heading=(number,title,copy)=>`<div class="cs-detail-heading"><span>${number}</span><div><h3>${title}</h3><p>${copy}</p></div></div>`;
 const card=item=>{const insight=answerInterpretation(item,language);return `<button class="cs-insight-card ${item.category}" data-question="${item.index}"><span class="cs-card-icon"><span class="cs-icon-tile">${icon(insight.icon)}</span><span>${esc(categories[item.category].short)}</span></span><strong>${esc(insight.title)}</strong><p>${esc(insight.meaning)}</p><span class="cs-detail-link">${t('See what shaped this','इसका आधार देखें')}${icon('arrow')}</span></button>`;};
 const emptyStrength=t('No answers fall in the strength group today. This check-in does not capture every strength you have.','आज इस समूह में कोई जवाब नहीं है। यह check-in आपकी हर मजबूती नहीं दिखा सकता।');
 const emptyAttention=t('No growth or sometimes responses in this check-in. Keep exploring how your supportive habits work in different situations.','इस check-in में बेहतरी या कभी-कभी वाले जवाब नहीं हैं। देखें कि मददगार आदतें अलग परिस्थितियों में कैसे काम करती हैं।');
 const title=details.mode==='growth'?t('Three places you could begin.','शुरुआत करने के तीन अवसर।'):details.mode==='explore'?t('Three patterns to understand better.','तीन पैटर्न जिन्हें और समझ सकते हैं।'):t('Three strengths to keep practising.','तीन मजबूतियाँ जिन्हें बनाए रख सकते हैं।');
 const practices=[t('Notice when this pattern shows up in an ordinary day.','रोज़मर्रा के दिन में ध्यान दें कि यह पैटर्न कब दिखता है।'),t('Try this once in a situation that feels manageable.','किसी आसान स्थिति में इसे एक बार आज़माएँ।'),t('Repeat what helps, and adjust it to fit your day.','जो मदद करे उसे दोहराएँ और अपने दिन के अनुसार बदलें।')];
 const stages=[[t('DAYS 1–4','दिन 1–4'),t('Notice','ध्यान दें')],[t('DAYS 5–8','दिन 5–8'),t('Try','आज़माएँ')],[t('DAYS 9–11','दिन 9–11'),t('Build','आगे बढ़ें')]];
 return `<div class="cs-expanded">
 <nav class="cs-chapter-nav" aria-label="${t('Consolidated report chapters','समेकित रिपोर्ट के हिस्से')}"><a href="#cs-patterns">${t('Strengths & growth','मजबूतियाँ और बेहतरी')}</a><a href="#cs-priorities">${t('Your focus areas','ध्यान देने के क्षेत्र')}</a><a href="#cs-journey">${t('Your 14-day plan','आपकी 14-दिन की योजना')}</a><a href="#cs-benefits">${t('Possible benefits','संभावित लाभ')}</a></nav>
 <section class="cs-detail-section" id="cs-patterns">${heading('01',t('What supports you. What needs space.','क्या मददगार है। कहाँ ध्यान दे सकते हैं।'),t('What your answers suggest about everyday life. Tap an insight to see the answer behind it.','आपके जवाब रोज़मर्रा के जीवन के बारे में क्या बताते हैं। किसी insight पर टैप करके उसका आधार देखें।'))}<div class="cs-sides"><div class="cs-side cs-side-support"><div class="cs-side-title">${icon('spark')}<h4>${t('Strengths to lean on','आपकी मजबूतियाँ')}</h4><span>${snapshot.counts.support} / 36</span></div><div class="cs-insight-grid">${details.strengths.length?details.strengths.map(card).join(''):`<p class="cs-empty">${emptyStrength}</p>`}</div></div><div class="cs-side cs-side-growth"><div class="cs-side-title">${icon('branch')}<h4>${details.mode==='growth'?t('Room to grow','जहाँ ध्यान दे सकते हैं'):t('Keep exploring','समझते रहें')}</h4><span>${details.mode==='growth'?snapshot.counts.focus:snapshot.counts.varies} / 36</span></div><div class="cs-insight-grid">${details.attention.length?details.attention.map(card).join(''):`<p class="cs-empty">${emptyAttention}</p>`}</div></div></div><p class="cs-section-note">${t('These are patterns from your answers, not fixed labels for who you are. Your full answer details and graphs follow below.','ये आपके जवाबों के पैटर्न हैं, आपकी स्थायी पहचान नहीं। सभी जवाब और ग्राफ नीचे मौजूद हैं।')}</p></section>
 <section class="cs-detail-section cs-comparison-section" id="cs-comparison">${heading('02',t('A little comparison context.','तुलना का थोड़ा संदर्भ।'),t('A clearly marked preview using 100 fictional responses per question. These numbers describe answer frequency, not how healthy or stable you are.','हर सवाल के 100 काल्पनिक जवाबों से बनी preview। ये संख्या जवाब की आवृत्ति बताती है, मानसिक स्वास्थ्य या स्थिरता की रैंकिंग नहीं।'))}<span class="cs-mock-tag">${t('MOCK DATA · NOT A WORLD RANK','MOCK डेटा · दुनिया की रैंक नहीं')}</span><div class="cs-comparison-grid">${details.comparison.map(item=>{const comparison=simulatedComparison(item.index,item.value);return `<button class="cs-compare-card" data-question="${item.index}"><span>${esc(item.label)}</span><strong>${comparison.same}<small>%</small></strong><p>${t('of the fictional responses chose','काल्पनिक जवाबों में चुना गया')} <b>“${esc(item.response)}”</b></p><div class="cs-compare-meter" aria-hidden="true"><i style="width:${comparison.below}%;background:#b3c3db"></i><i style="width:${comparison.same}%;background:#8473a7"></i><i style="width:${comparison.above}%;background:#e3dcec"></i></div><div class="cs-compare-key"><span>${comparison.below}% ${t('less often','कम बार')}</span><b>${comparison.same}% ${t('same','वही')}</b><span>${comparison.above}% ${t('more often','ज़्यादा बार')}</span></div><span class="cs-source">${item.id} · ${t('100 fictional responses','100 काल्पनिक जवाब')}</span></button>`;}).join('')}</div></section>
 <section class="cs-detail-section" id="cs-priorities">${heading('03',title,t('Suggested starting points from your answers. Choose the one that matters most to you; this order is not a clinical priority ranking.','आपके जवाबों से चुनी गई शुरुआत। आपके लिए जो उपयोगी हो उसे चुनें; यह चिकित्सकीय प्राथमिकता की रैंकिंग नहीं है।'))}<div class="cs-priority-list">${details.priorities.map((item,i)=>{const insight=answerInterpretation(item,language);return `<article class="cs-priority"><span class="cs-priority-number">0${i+1}</span><div><span class="cs-priority-area">${esc(areas[Math.floor(item.index/6)].name)} · ${esc(categories[item.category].short)}</span><h4>${esc(insight.title)}</h4><p>${esc(insight.meaning)}</p><div class="cs-action-tip"><span>${icon(insight.icon)}</span><div><strong>${t('One small step','एक छोटा कदम')}</strong><p>${esc(insight.practice)}</p></div></div></div><button data-question="${item.index}" aria-label="${t('Explore','देखें')} ${esc(insight.title)}">${icon('arrow')}</button></article>`;}).join('')}</div></section>
 <section class="cs-detail-section cs-journey-section" id="cs-journey">${heading('04',t('A gentle 14-day reflection plan.','14 दिनों की एक सरल reflection योजना।'),t('A suggested pace, built around the answers above. Spend a few minutes on one small practice; repeat or adjust a stage whenever useful.','ऊपर के जवाबों पर आधारित एक सुझाई गई गति। किसी एक छोटे अभ्यास पर कुछ मिनट दें; ज़रूरत के अनुसार चरण दोहराएँ या बदलें।'))}<div class="cs-journey-grid">${details.priorities.map((item,i)=>{const insight=answerInterpretation(item,language);return `<article class="cs-journey-card"><span class="cs-day">${stages[i][0]}</span><span class="cs-journey-icon">${icon(insight.icon)}</span><span class="cs-stage">${stages[i][1]}</span><h4>${esc(insight.title)}</h4><p class="cs-practice">${practices[i]}</p><p class="cs-practice-prompt">${esc(insight.practice)}</p></article>`;}).join('')}<article class="cs-journey-card cs-review-card"><span class="cs-day">${t('DAYS 12–14','दिन 12–14')}</span><span class="cs-journey-icon">${icon('leaf')}</span><span class="cs-stage">${t('Reflect','विचार करें')}</span><h4>${t('Keep what felt useful.','जो उपयोगी लगा उसे साथ रखें।')}</h4><p>${t('Recall one moment when you tried a small step. What helped, what was difficult, and what would you like to repeat?','कोई एक पल याद करें जब आपने सुझाव आज़माया। क्या मददगार था, क्या मुश्किल था और क्या दोहराना चाहेंगे?')}</p><span class="cs-source">${t('Your experience sets the pace','गति अपने अनुभव के अनुसार रखें')}</span></article></div></section>
 <section class="cs-detail-section" id="cs-benefits">${heading('05',t('What these small shifts could help with.','ये छोटे बदलाव किसमें मदद कर सकते हैं।'),t('Possible benefits to notice over time, rather than targets you must achieve in 14 days.','समय के साथ ध्यान देने योग्य संभावित लाभ। इन्हें 14 दिनों में हासिल करने का दबाव नहीं है।'))}<div class="cs-benefit-grid">${details.priorities.map(item=>`<article class="cs-benefit-card"><span>${icon(areas[Math.floor(item.index/6)].icon)}</span><h4>${esc(areas[Math.floor(item.index/6)].name)}</h4><p>${esc(item.benefit)}</p><small>${t('Connected to','संबंधित सवाल')} ${item.id}</small></article>`).join('')}</div><div class="cs-reflection-prompt">${icon('orbit')}<div><strong>${t('One thought to take with you','एक सवाल अपने साथ रखें')}</strong><p>${t('In the next two weeks, which everyday moment would you like to handle a little differently?','अगले दो हफ़्तों में किस रोज़मर्रा के पल को थोड़ा अलग तरीके से सँभालना चाहेंगे?')}</p></div></div><p class="cs-section-note">${t('This is a reflection on your submitted answers, not a diagnosis. Suggested activities and benefits are possibilities, not guaranteed outcomes.','यह आपके दिए जवाबों पर reflection है, निदान नहीं। गतिविधियाँ और लाभ संभावनाएँ हैं, गारंटी नहीं।')}</p></section>
 <div class="cs-details-end"><div><span class="small-label">${t('THE FULL PICTURE CONTINUES','पूरी तस्वीर आगे भी है')}</span><h3>${t('Now explore the evidence behind it.','अब इसके पीछे के जवाब देखें।')}</h3><p>${t('All six areas, all 36 answers, and your detailed next steps follow below.','नीचे सभी छह पहलू, सभी 36 जवाब और विस्तृत अगले कदम मौजूद हैं।')}</p></div><a href="#six-areas">${t('Explore your graphs','अपने ग्राफ देखें')}${icon('arrow')}</a></div>
 </div>`;
}
